#!/bin/sh
# ---------------------------------------------------------------------------
# Template for Tomcat's bin/setenv.sh.
#
# Do not edit this file in place on a server: scripts/host-app.sh renders it with
# that deployment's generated secrets and writes it to $CATALINA_BASE/bin/setenv.sh
# with mode 0750. It is kept in the repository as the documented, reviewable list
# of every environment variable the application reads.
#
# Every value here is a placeholder for an injected secret. Nothing in this file
# may ever contain a real credential (spec §STRICT RESTRICTIONS).
# ---------------------------------------------------------------------------

# JVM
export JAVA_HOME="${JAVA_HOME:-/opt/infeara/jdk-17}"
# Heap sized for a single-node deployment: the worker (outbox relay, job engine,
# email dispatcher, inbound discovery) runs inside the same JVM as the API.
export CATALINA_OPTS="${CATALINA_OPTS} -Xms512m -Xmx1536m -XX:+UseG1GC \
  -XX:+ExitOnOutOfMemoryError -Dfile.encoding=UTF-8 -Duser.timezone=UTC"

# Datasource (MariaDB 11.4 is the only supported database)
# These five names are read directly by application.yml — do not rename them.
export DB_HOST="127.0.0.1"
export DB_PORT="3306"
export DB_NAME="infeara_sales"
export DB_USER="infeara"
export DB_PASSWORD="__INJECTED__"
export DB_POOL_MAX="20"
export DB_POOL_MIN="4"

# Application
export APP_BASE_URL="https://sales.example.com"
export APP_ENV="production"
export APP_TIMEZONE="Asia/Kolkata"
export CORS_ALLOWED_ORIGINS=""

# Credential encryption (AES-256-GCM). Generate with: openssl rand -base64 32
# Rotate by moving the old key to SMTP_SECRET_PREVIOUS_KEYS as "<id>:<base64>".
export SMTP_SECRET_ENCRYPTION_KEY="__INJECTED__"
export SMTP_SECRET_ENCRYPTION_KEY_ID="k1"
export SMTP_SECRET_PREVIOUS_KEYS=""

# First-run provisioning (only used while the workspace has no users)
export BOOTSTRAP_WORKSPACE_NAME="Infeara Technologies"
export BOOTSTRAP_WORKSPACE_SLUG="infeara"
export BOOTSTRAP_WORKSPACE_TIMEZONE="Asia/Kolkata"
export BOOTSTRAP_ADMIN_EMAIL="__INJECTED__"
export BOOTSTRAP_ADMIN_PASSWORD="__INJECTED__"
export BOOTSTRAP_ADMIN_NAME="Workspace Administrator"

# Worker (durable outbox relay + job engine). Safe to disable on a read-only node.
export WORKER_ENABLED="true"
export WORKER_INSTANCE_ID=""

# Inbound mailbox sync (addendum 3.2). Poll discovery enqueues one leased job per
# active mailbox; the actual IMAP session runs outside any database transaction.
export EMAIL_INBOUND_DISCOVERY_INTERVAL_MS="60000"
export EMAIL_INBOUND_MAX_BODY_CHARS="200000"
export EMAIL_INBOUND_MAX_ATTACHMENT_BYTES="10485760"
export EMAIL_INBOUND_MAX_ATTACHMENTS="20"
export EMAIL_INBOUND_MAX_MESSAGES_PER_SYNC="50"
export EMAIL_BUSINESS_HOURS_START="09:00"
export EMAIL_BUSINESS_HOURS_END="18:00"

# AI providers (OpenRouter preferred, OpenAI fallback). Leaving both empty is a
# supported state: analysis is reported unavailable instead of faked.
export AI_PREFERRED_PROVIDER="OPENROUTER"
export AI_OPENROUTER_API_KEY=""
export AI_OPENROUTER_MODEL="openai/gpt-4o-mini"
export AI_OPENAI_API_KEY=""
export AI_OPENAI_MODEL="gpt-4o-mini"
export AI_TIMEOUT_SECONDS="30"

# Calendly
export CALENDLY_WEBHOOK_TOLERANCE_SECONDS="180"

# Logging: never log request bodies or credentials.
export LOG_LEVEL_APP="INFO"
